[package]
name = "tinyagents-integration-tests"
version.workspace = true
edition.workspace = true
license.workspace = true
repository.workspace = true
publish = false

[dependencies]
anyhow = "1"
async-trait = "0.1"
chrono = "0.4"
dotenvy = "0.15"
futures = "0.3"
reqwest = { version = "0.12", default-features = false, features = ["json", "rustls-tls"] }
rusqlite = { version = "0.40", features = ["bundled"] }
serde = { version = "1", features = ["derive"] }
serde_json = "1"
tempfile = "3"
tinyagents-graph = { path = "../tinyagents-graph" }
tinyagents-harness = { path = "../tinyagents-harness" }
tinyagents-definition = { path = "../tinyagents-definition" }
tinyagents-orchestration = { path = "../tinyagents-orchestration" }
tinyagents-registry = { path = "../tinyagents-registry" }
tinyagents-session = { path = "../tinyagents-session" }
tinyinference-llm = { path = "../../vendor/tinyinference/crates/tinyinference-llm", version = "0.3.0" }
tinyinference-embeddings = { path = "../../vendor/tinyinference/crates/tinyinference-embeddings", version = "0.3.0" }
tinytools = { path = "../../vendor/tinytools/crates/tinytools", version = "0.3.0" }
tokio = { version = "1", features = ["macros", "rt-multi-thread", "time", "test-util"] }

[features]
default = []
sqlite = ["tinyagents-graph/sqlite", "tinyagents-harness/sqlite"]
