    "tinyagents-graph/tracing",
    "tinyagents-harness/tracing",
    "tinyagents-registry/tracing",
    "tinyagents-session/tracing",
]

[lints.rust]
unused_imports = "allow"

//! End-to-end regression tests for transcript compaction defects.
//!
//! Every test in this file is written **only against APIs that existed before
//! the fixes**, so each one compiles against the unfixed crate and fails there.
//! That is deliberate: a regression test for a structural bug is worth little if
//! it can only be expressed in terms of the fix's own new surface.
//!
//! The three defects covered:
//!
//! - **Orphaned tool pairing.** `SummarizationPolicy::plan` and all three
//!   `TrimStrategy` variants cut at a blind index, severing an assistant
//!   `tool_calls` turn from the `tool` messages answering it. The rebuilt
//!   request then carries a `role:"tool"` with no preceding `tool_calls`, which
//!   OpenAI rejects with a `400` and Anthropic rejects as a `tool_result` with
//!   no matching `tool_use`.
//! - **Token estimation blind to tool calls.** An assistant turn that only
//!   calls tools has empty `content`, so it estimated at zero and no compaction
//!   gate ever fired on the runs that needed it most.
//! - **History erased by the default summarizer.** `ConcatSummarizer` built its
//!   output from `Message::text()`, which renders tool calls and tool results as
//!   the empty string.

use tinyagents_harness::summarization::{
    ConcatSummarizer, SummarizationPolicy, Summarizer, TrimStrategy, trim_messages,
};
use tinyinference_llm::message::{AssistantMessage, Message};
use tinyinference_llm::tool::ToolCall;

/// The provider invariant, checked locally so this file depends on no new
/// crate surface: every `tool` message must be preceded by an assistant turn
/// declaring its id, and every declared call must be answered.
fn pairing_intact(messages: &[Message]) -> bool {
    let mut declared: Vec<&str> = Vec::new();
    let mut answered: Vec<&str> = Vec::new();

    for message in messages {
        match message {
            Message::Assistant(assistant) => {
                declared.extend(assistant.tool_calls.iter().map(|call| call.id.as_str()));
            }
            Message::Tool(tool) => {
                if !declared.contains(&tool.tool_call_id.as_str()) {
                    return false;
                }
                answered.push(tool.tool_call_id.as_str());
            }
            _ => {}
        }
    }

    declared.iter().all(|id| answered.contains(id))
}

fn assistant_calling(id: &str) -> Message {
    Message::Assistant(AssistantMessage {
        id: None,
        content: Vec::new(),
        tool_calls: vec![ToolCall::new(
            id,
            "get_weather",
            serde_json::json!({"city": "Paris"}),
        )],
        usage: None,

        origin: None,
    })
}

/// `[system, user, assistant(tool_calls=[c1]), tool(c1), assistant]` — the
/// shape a `keep_last = 2` cut splits down the middle.
fn tool_transcript() -> Vec<Message> {
    vec![
        Message::system("you are helpful"),
        Message::user("weather in Paris?"),
        assistant_calling("c1"),
        Message::tool("c1", r#"{"temp_c":21}"#),
        Message::assistant("It is 21C."),
    ]
}

#[test]
fn summarization_plan_never_orphans_a_tool_result() {
    let policy = SummarizationPolicy {
        keep_last: 2,
        ..Default::default()
    };
    let (_to_summarize, to_keep) = policy.plan(&tool_transcript());

    assert!(
        pairing_intact(&to_keep),
        "plan kept a tool result whose assistant tool-call turn was summarized away: {to_keep:#?}"
    );
}

#[test]
fn keep_last_never_orphans_a_tool_result() {
    let trimmed = trim_messages(&tool_transcript(), &TrimStrategy::KeepLast(2));
    assert!(
        pairing_intact(&trimmed),
        "KeepLast produced a slice a provider would reject: {trimmed:#?}"
    );
}

#[test]
fn keep_first_and_last_never_orphans_either_end() {
    let messages = vec![
        Message::user("one"),
        assistant_calling("c1"),
        Message::tool("c1", "r1"),
        Message::user("two"),
        assistant_calling("c2"),
        Message::tool("c2", "r2"),
        Message::assistant("done"),
    ];
    let trimmed = trim_messages(
        &messages,
        &TrimStrategy::KeepFirstAndLast { first: 2, last: 2 },
    );
    assert!(
        pairing_intact(&trimmed),
        "KeepFirstAndLast left an unanswered call or an unpaired result: {trimmed:#?}"
    );
}

#[test]
fn max_tokens_never_orphans_a_tool_result() {
    // The assistant turn carries visible text as well as its tool call, so the
    // budget loop stops *between* the call and its result — the only way a
    // front-dropping token trim can orphan one.
    let narrating_call = Message::Assistant(AssistantMessage {
        id: None,
        content: vec![tinyinference_llm::message::ContentBlock::Text(
            "Let me look that up. ".repeat(20),
        )],
        tool_calls: vec![ToolCall::new(
            "c1",
            "get_weather",
            serde_json::json!({"city": "Paris"}),
        )],
        usage: None,

        origin: None,
    });
    let messages = vec![
        Message::user("x".repeat(40)),
        narrating_call,
        Message::tool("c1", "r1"),
        Message::assistant("done"),
    ];
    let trimmed = trim_messages(&messages, &TrimStrategy::MaxTokens(3));
    assert!(
        pairing_intact(&trimmed),
        "MaxTokens produced a slice a provider would reject: {trimmed:#?}"
    );
}

#[test]
fn a_tool_only_assistant_turn_trips_the_compaction_gate() {
    // A 50-turn run whose assistant messages are all tool calls with 2 KB
    // argument blobs used to estimate at zero tokens, so the window overflowed
    // uncompacted.
    let heavy = Message::Assistant(AssistantMessage {
        id: None,
        content: Vec::new(),
        tool_calls: vec![ToolCall::new(
            "c1",
            "search",
            serde_json::json!({"query": "q".repeat(2_000)}),
        )],
        usage: None,

        origin: None,
    });
    assert_eq!(heavy.text(), "", "precondition: no visible text");

    let policy = SummarizationPolicy {
        trigger_tokens: 100,
        ..Default::default()
    };
    assert!(
        policy.should_summarize(&[heavy]),
        "a 2 KB tool-call turn must trip a 100-token trigger"
    );
}

#[tokio::test]
async fn the_default_summarizer_preserves_tool_history() {
    let record = ConcatSummarizer
        .summarize(&tool_transcript())
        .await
        .expect("summarizing a non-empty transcript must succeed");
    let summary = record.summary.text();

    assert!(
        summary.contains("get_weather"),
        "the tool name was erased: {summary}"
    );
    assert!(
        summary.contains("Paris"),
        "the tool arguments were erased: {summary}"
    );
    assert!(
        summary.contains("temp_c"),
        "the tool result was erased: {summary}"
    );
}

//! Unit tests for `parse_auth_status_json`, covering the subscription,
//! API-key, signed-out, and malformed/unknown-shape branches.

use super::*;

#[test]
fn parses_claude_ai_subscription() {
    let raw = r#"{
        "loggedIn": true,
        "authMethod": "claude.ai",
        "apiProvider": "firstParty",
        "email": "user@example.com",
        "subscriptionType": "max"
    }"#;
    match parse_auth_status_json(raw) {
        AuthSource::Subscription {
            account_email,
            subscription_type,
            expires_at,
        } => {
            assert_eq!(account_email.as_deref(), Some("user@example.com"));
            assert_eq!(subscription_type.as_deref(), Some("max"));
            assert!(expires_at.is_none());
        }
        other => panic!("expected Subscription, got {other:?}"),
    }
}

#[test]
fn subscription_tolerates_missing_email_and_type() {
    let raw = r#"{ "loggedIn": true, "authMethod": "claude.ai" }"#;
    match parse_auth_status_json(raw) {
        AuthSource::Subscription {
            account_email,
            subscription_type,
            ..
        } => {
            assert!(account_email.is_none());
            assert!(subscription_type.is_none());
        }
        other => panic!("expected Subscription, got {other:?}"),
    }
}

#[test]
fn logged_in_via_api_key_method_maps_to_api_key_env() {
    let raw = r#"{ "loggedIn": true, "authMethod": "console", "apiProvider": "console" }"#;
    assert_eq!(parse_auth_status_json(raw), AuthSource::ApiKeyEnv);
}

#[test]
fn logged_in_without_auth_method_is_unknown_not_api_key() {
    // Schema drift: `loggedIn: true` but no `authMethod`. Must NOT be
    // reported as the definite `api_key_env` signed-in state — fall to
    // `unknown` so the UI shows "couldn't determine" instead.
    let raw = r#"{ "loggedIn": true }"#;
    match parse_auth_status_json(raw) {
        AuthSource::Unknown { reason } => assert!(reason.is_some()),
        other => panic!("expected Unknown, got {other:?}"),
    }
}

#[test]
fn logged_out_maps_to_none() {
    let raw = r#"{ "loggedIn": false }"#;
    assert_eq!(parse_auth_status_json(raw), AuthSource::None);
}

#[test]
fn missing_logged_in_field_is_unknown() {
    let raw = r#"{ "authMethod": "claude.ai", "email": "user@example.com" }"#;
    match parse_auth_status_json(raw) {
        AuthSource::Unknown { reason } => assert!(reason.is_some()),
        other => panic!("expected Unknown, got {other:?}"),
    }
}

#[test]
fn malformed_json_is_unknown_not_signed_out() {
    match parse_auth_status_json("not json at all") {
        AuthSource::Unknown { reason } => assert!(reason.is_some()),
        other => panic!("expected Unknown, got {other:?}"),
    }
}

#[test]
fn api_key_env_short_circuits_probe() {
    let _env = super::super::ENV_TEST_LOCK
        .lock()
        .unwrap_or_else(|e| e.into_inner());
    let prev = std::env::var("ANTHROPIC_API_KEY").ok();
    super::super::test_set_env("ANTHROPIC_API_KEY", "sk-ant-test");

    let s = probe();
    assert_eq!(s.source, AuthSource::ApiKeyEnv);

    match prev {
        Some(v) => super::super::test_set_env("ANTHROPIC_API_KEY", v),
        None => super::super::test_remove_env("ANTHROPIC_API_KEY"),
    }
}

//! Unit tests for `ANTHROPIC_API_KEY` resolution precedence.

use super::*;

#[test]
fn defaults_to_cli_credentials_without_env() {
    let _env = super::super::ENV_TEST_LOCK
        .lock()
        .unwrap_or_else(|e| e.into_inner());
    let prev = std::env::var("ANTHROPIC_API_KEY").ok();
    super::super::test_remove_env("ANTHROPIC_API_KEY");

    let (src, key) = resolve();
    assert_eq!(src, AuthSource::CliCredentials);
    assert!(key.is_none());

    if let Some(v) = prev {
        super::super::test_set_env("ANTHROPIC_API_KEY", v);
    }
}

//! Integration coverage for the runnable subconscious-loop example.

#[path = "../examples/subconscious_loop/autonomous_loop.rs"]
mod autonomous_loop;

use autonomous_loop::{
    SystemState, WorldDiff, build_subconscious_loop_graph, run_subconscious_loop,
};

#[tokio::test]
async fn normal_loop_retrieves_memory_and_holds_single_diff() {
    let graph = build_subconscious_loop_graph().expect("graph compiles");
    let run = graph
        .run(SystemState::new(
            "web",
            "Shift the resource matrix by a small amount.",
        ))
        .await
        .expect("graph runs");

    let visited: Vec<_> = run.visited.iter().map(|node| node.as_str()).collect();
    assert_eq!(
        visited,
        vec![
            "channel_ingestion",
            "frontend_agent",
            "agent_execution",
            "summarization_gate",
            "frontend_agent",
            "context_manager_hook",
        ]
    );
    assert!(run.state.channel_response.contains("Completed. Output"));
    assert_eq!(run.state.retrieved_context.len(), 1);
    assert_eq!(run.state.sequential_diffs.len(), 1);
    assert!(run.state.gated_world_summary.is_none());
    assert!(!run.state.trigger_subconscious);
    assert!(run.state.subconscious_steering.is_empty());

    let helper_state = run_subconscious_loop(SystemState::new("web", "Routine helper smoke."))
        .await
        .expect("helper runs");
    assert!(helper_state.channel_response.contains("Completed. Output"));
}

#[tokio::test]
async fn reasoning_escalation_forces_gate_and_resets_trigger() {
    let graph = build_subconscious_loop_graph().expect("graph compiles");
    let run = graph
        .run(SystemState::new(
            "telegram",
            "CRITICAL cascading sub-agent failure during resource reallocation.",
        ))
        .await
        .expect("graph runs");

    let visited: Vec<_> = run.visited.iter().map(|node| node.as_str()).collect();
    assert!(visited.contains(&"subconscious_eval"));
    assert!(run.state.sequential_diffs.is_empty());
    assert!(run.state.gated_world_summary.is_none());
    assert!(!run.state.trigger_subconscious);
    assert!(
        run.state
            .subconscious_steering
            .contains("Lower sub-agent temperature")
    );
    assert!(
        run.state
            .semantic_history
            .iter()
            .any(|trace| trace.contains("error_code=SUBAGENT_CASCADE"))
    );
}

#[tokio::test]
async fn sequential_diff_threshold_routes_through_subconscious() {
    let graph = build_subconscious_loop_graph().expect("graph compiles");
    let mut state = SystemState::new("web", "Shift the resource matrix again.");
    state.sequential_diffs = vec![
        WorldDiff::new("resource_shift", 9, "stable"),
        WorldDiff::new("resource_shift", 11, "stable"),
    ];

    let run = graph.run(state).await.expect("graph runs");

    let visited: Vec<_> = run.visited.iter().map(|node| node.as_str()).collect();
    assert!(visited.contains(&"subconscious_eval"));
    assert!(run.state.sequential_diffs.is_empty());
    assert!(run.state.gated_world_summary.is_none());
    assert_eq!(
        run.state.subconscious_steering,
        "STEERING_DIRECTIVE: System stable. Preserve current execution policy."
    );
    assert!(
        run.state
            .event_log
            .iter()
            .any(|entry| entry.contains("Aggregated 3 operational shifts"))
    );
}

#[tokio::test]
async fn context_manager_evicts_semantic_history_to_long_term_memory() {
    let graph = build_subconscious_loop_graph().expect("graph compiles");
    let mut state = SystemState::new("web", "Perform routine work.");
    state.context_utilization = 0.84;
    let initial_memory_count = state.long_term_memory.len();

    let run = graph.run(state).await.expect("graph runs");

    let visited: Vec<_> = run.visited.iter().map(|node| node.as_str()).collect();
    assert!(!visited.contains(&"subconscious_eval"));
    assert_eq!(run.state.context_utilization, 0.2);
    assert_eq!(
        run.state.semantic_history,
        vec!["--- semantic history evicted to vector DB ---".to_string()]
    );
    assert!(run.state.long_term_memory.len() > initial_memory_count);
}

//! Runs the autonomous subconscious-loop graph example.
//!
//! ```text
//! cargo run --example subconscious_loop
//! ```

mod autonomous_loop;

use autonomous_loop::{SystemState, run_subconscious_loop};
use tinyagents_harness::Result;

#[tokio::main]
async fn main() -> Result<()> {
    let final_state = run_subconscious_loop(SystemState::new(
        "telegram",
        "Reallocate the resource matrix and report whether the system remains stable.",
    ))
    .await?;

    println!("=== Autonomous closed-loop subconscious example ===");
    println!("channel response : {}", final_state.channel_response);
    println!("retrieved context: {:?}", final_state.retrieved_context);
    println!("semantic history : {:?}", final_state.semantic_history);
    println!("sequential diffs : {:?}", final_state.sequential_diffs);
    println!("steering         : {}", final_state.subconscious_steering);
    println!("context usage    : {:.2}", final_state.context_utilization);
    println!("visited events   :");
    for event in &final_state.event_log {
        println!("  - {event}");
    }

    Ok(())
}

//! A fully offline, testable version of the autonomous closed-loop harness.
//!
//! The example maps the Python/LangGraph reference architecture onto
//! TinyAgents' typed graph runtime:
//!
//! - channel ingestion and front-end response management run as lightweight
//!   graph nodes;
//! - the reasoning node performs deterministic retrieval, sub-agent simulation,
//!   semantic extraction, sequential diff generation, and event escalation;
//! - the summarization gate compresses world-state diffs before the deep layer;
//! - the context manager evicts semantic history into a mock vector store when
//!   utilization crosses a threshold;
//! - the subconscious node consumes gated summaries and emits a short steering
//!   directive while resetting escalation state.
//!
//! The implementation uses deterministic functions instead of live LLM calls so
//! `cargo run --example subconscious_loop` and the integration tests stay
//! offline and reproducible.

use tinyagents_graph::ClosureStateReducer;
use tinyagents_graph::END;
use tinyagents_graph::*;
use tinyagents_harness::*;
use tinyagents_registry::*;

const DIFF_GATE_MIN_SEQUENCE: usize = 3;
const CONTEXT_EVICTION_THRESHOLD: f32 = 0.85;

/// One visible channel message in the surface layer.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct ChannelMessage {
    pub role: String,
    pub content: String,
}

/// A compact world-state mutation produced by the reasoning layer.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct WorldDiff {
    pub event: String,
    pub magnitude: i32,
    pub status: String,
}

impl WorldDiff {
    pub fn new(event: impl Into<String>, magnitude: i32, status: impl Into<String>) -> Self {
        Self {
            event: event.into(),
            magnitude,
            status: status.into(),
        }
    }
}

/// Dense package forwarded to the subconscious layer.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct GatedWorldSummary {
    pub macro_trend: String,
    pub critical_events: usize,
    pub total_magnitude: i32,
}

/// A mock long-term memory record. In production this would be a vector DB row.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MemoryRecord {
    pub key: String,
    pub text: String,
}

impl MemoryRecord {
    pub fn new(key: impl Into<String>, text: impl Into<String>) -> Self {
        Self {
            key: key.into(),
            text: text.into(),
        }
    }
}

/// The state carried through the closed-loop graph.
#[derive(Clone, Debug, PartialEq)]
pub struct SystemState {
    pub messages: Vec<ChannelMessage>,
    pub channel_source: String,
    pub raw_channel_payload: String,
    pub agent_instructions: String,
    pub agent_reply: String,
    pub channel_response: String,
    pub subconscious_steering: String,
    pub semantic_history: Vec<String>,
    pub sequential_diffs: Vec<WorldDiff>,
    pub gated_world_summary: Option<GatedWorldSummary>,
    pub context_utilization: f32,
    pub trigger_subconscious: bool,
    pub cron_due: bool,
    pub long_term_memory: Vec<MemoryRecord>,
    pub retrieved_context: Vec<String>,
    pub event_log: Vec<String>,
}

impl SystemState {
    /// Builds an initial channel packet with a seeded memory corpus.
    pub fn new(channel_source: impl Into<String>, raw_payload: impl Into<String>) -> Self {
        Self {
            messages: Vec::new(),
            channel_source: channel_source.into(),
            raw_channel_payload: raw_payload.into(),
            agent_instructions: String::new(),
            agent_reply: String::new(),
            channel_response: String::new(),
            subconscious_steering: String::new(),
            semantic_history: Vec::new(),
            sequential_diffs: Vec::new(),
            gated_world_summary: None,
            context_utilization: 0.1,
            trigger_subconscious: false,
            cron_due: false,
            long_term_memory: vec![
                MemoryRecord::new(
                    "resource",
                    "Historical trace: resource reallocation occurred in cycle 42.",
                ),
                MemoryRecord::new(
                    "subagent",
                    "Historical trace: repeated sub-agent failures respond well to lower temperature.",
                ),
            ],
            retrieved_context: Vec::new(),
            event_log: Vec::new(),
        }
    }
}

/// Partial updates merged at graph step boundaries.
#[derive(Clone, Debug, Default)]
pub struct StatePatch {
    pub messages: Vec<ChannelMessage>,
    pub agent_instructions: Option<String>,
    pub agent_reply: Option<String>,
    pub channel_response: Option<String>,
    pub subconscious_steering: Option<String>,
    pub append_semantic_history: Vec<String>,
    pub replace_semantic_history: Option<Vec<String>>,
    pub append_sequential_diffs: Vec<WorldDiff>,
    pub clear_sequential_diffs: bool,
    pub set_gated_world_summary: Option<GatedWorldSummary>,
    pub clear_gated_world_summary: bool,
    pub context_utilization: Option<f32>,
    pub context_utilization_delta: f32,
    pub trigger_subconscious: Option<bool>,
    pub cron_due: Option<bool>,
    pub append_long_term_memory: Vec<MemoryRecord>,
    pub append_retrieved_context: Vec<String>,
    pub append_event_log: Vec<String>,
}

impl StatePatch {
    fn event(event: impl Into<String>) -> Self {
        Self {
            append_event_log: vec![event.into()],
            ..Self::default()
        }
    }
}

/// Builds the closed-loop graph.
pub fn build_subconscious_loop_graph() -> Result<CompiledGraph<SystemState, StatePatch>> {
    GraphBuilder::<SystemState, StatePatch>::new()
        .set_reducer(ClosureStateReducer::new(apply_patch))
        .add_node("channel_ingestion", channel_ingestion_node)
        .add_node("frontend_agent", frontend_agent_node)
        .add_node("agent_execution", agent_execution_node)
        .add_node("summarization_gate", summarization_gate_node)
        .add_node("context_manager_hook", context_manager_hook_node)
        .add_node("subconscious_eval", subconscious_eval_node)
        .set_entry("channel_ingestion")
        .add_edge("channel_ingestion", "frontend_agent")
        .add_conditional_edges(
            "frontend_agent",
            automated_loop_router,
            [
                ("agent_execution", "agent_execution"),
                ("context_manager_hook", "context_manager_hook"),
            ],
        )
        .add_edge("agent_execution", "summarization_gate")
        .add_edge("summarization_gate", "frontend_agent")
        .add_conditional_edges(
            "context_manager_hook",
            subconscious_router,
            [
                ("subconscious_eval", "subconscious_eval"),
                ("END", "__end__"),
            ],
        )
        .set_finish("subconscious_eval")
        .with_node_kind("channel_ingestion", "channel")
        .with_node_kind("frontend_agent", "quick_llm")
        .with_node_kind("agent_execution", "reasoning_llm")
        .with_node_kind("summarization_gate", "compression_gate")
        .with_node_kind("context_manager_hook", "context_manager")
        .with_node_kind("subconscious_eval", "subconscious_llm")
        .compile()
}

/// Runs the example graph from an initial state.
pub async fn run_subconscious_loop(initial: SystemState) -> Result<SystemState> {
    let graph = build_subconscious_loop_graph()?;
    Ok(graph.run(initial).await?.state)
}

fn apply_patch(mut state: SystemState, patch: StatePatch) -> Result<SystemState> {
    state.messages.extend(patch.messages);

    if let Some(value) = patch.agent_instructions {
        state.agent_instructions = value;
    }
    if let Some(value) = patch.agent_reply {
        state.agent_reply = value;
    }
    if let Some(value) = patch.channel_response {
        state.channel_response = value;
    }
    if let Some(value) = patch.subconscious_steering {
        state.subconscious_steering = value;
    }

    if let Some(history) = patch.replace_semantic_history {
        state.semantic_history = history;
    }
    state.semantic_history.extend(patch.append_semantic_history);

    if patch.clear_sequential_diffs {
        state.sequential_diffs.clear();
    }
    state.sequential_diffs.extend(patch.append_sequential_diffs);

    if patch.clear_gated_world_summary {
        state.gated_world_summary = None;
    }
    if let Some(summary) = patch.set_gated_world_summary {
        state.gated_world_summary = Some(summary);
    }

    if let Some(value) = patch.context_utilization {
        state.context_utilization = value.clamp(0.0, 1.0);
    }
    if patch.context_utilization_delta != 0.0 {
        state.context_utilization =
            (state.context_utilization + patch.context_utilization_delta).clamp(0.0, 1.0);
    }

    if let Some(value) = patch.trigger_subconscious {
        state.trigger_subconscious = value;
    }
    if let Some(value) = patch.cron_due {
        state.cron_due = value;
    }

    state.long_term_memory.extend(patch.append_long_term_memory);
    state
        .retrieved_context
        .extend(patch.append_retrieved_context);
    state.event_log.extend(patch.append_event_log);

    Ok(state)
}

fn channel_ingestion_node(state: SystemState, _ctx: NodeContext) -> impl FutureNode {
    async move {
        Ok(NodeResult::Update(StatePatch {
            messages: vec![ChannelMessage {
                role: "user".to_string(),
                content: state.raw_channel_payload.clone(),
            }],
            append_event_log: vec![format!(
                "channel_ingestion: packet from {}",
                state.channel_source
            )],
            ..StatePatch::default()
        }))
    }
}

fn frontend_agent_node(state: SystemState, _ctx: NodeContext) -> impl FutureNode {
    async move {
        if state.agent_reply.is_empty() {
            Ok(NodeResult::Update(StatePatch {
                agent_instructions: Some(format!(
                    "AUTONOMOUS_EXECUTE: {}",
                    state.raw_channel_payload
                )),
                append_event_log: vec!["frontend_agent: deferred macro instruction".to_string()],
                ..StatePatch::default()
            }))
        } else {
            Ok(NodeResult::Update(StatePatch {
                channel_response: Some(format!("Completed. Output: {}", state.agent_reply)),
                append_event_log: vec!["frontend_agent: compiled final response".to_string()],
                ..StatePatch::default()
            }))
        }
    }
}

fn agent_execution_node(state: SystemState, _ctx: NodeContext) -> impl FutureNode {
    async move {
        let instructions = state.agent_instructions.clone();
        let retrieved = retrieve_context(&state.long_term_memory, &instructions);
        let anomaly = contains_any(
            &instructions,
            &["critical", "cascade", "failure", "anomaly"],
        );
        let magnitude = if anomaly {
            91
        } else if contains_any(&instructions, &["resource", "matrix", "allocation"]) {
            14
        } else {
            4
        };
        let status = if anomaly { "degraded" } else { "stable" };
        let semantic_trace = format!(
            "[Semantic Extraction] entity=sub_agents event=resource_shift magnitude={magnitude}% status={status} error_code={}",
            if anomaly { "SUBAGENT_CASCADE" } else { "NONE" }
        );
        let force_subconscious = anomaly || state.context_utilization >= 0.9;

        Ok(NodeResult::Update(StatePatch {
            agent_reply: Some(format!(
                "Pipeline mutations executed via sub-agents; {} memory traces retrieved.",
                retrieved.len()
            )),
            append_semantic_history: vec![semantic_trace],
            append_sequential_diffs: vec![WorldDiff::new("resource_shift", magnitude, status)],
            trigger_subconscious: Some(force_subconscious),
            context_utilization_delta: if anomaly { 0.2 } else { 0.05 },
            append_retrieved_context: retrieved,
            append_event_log: vec![
                "agent_execution: retrieved long-term context".to_string(),
                format!("agent_execution: emitted sequential diff status={status}"),
            ],
            ..StatePatch::default()
        }))
    }
}

fn summarization_gate_node(state: SystemState, _ctx: NodeContext) -> impl FutureNode {
    async move {
        let should_forward =
            state.sequential_diffs.len() >= DIFF_GATE_MIN_SEQUENCE || state.trigger_subconscious;

        if !should_forward {
            return Ok(NodeResult::Update(StatePatch::event(
                "summarization_gate: threshold not met; holding diffs",
            )));
        }

        Ok(NodeResult::Update(StatePatch {
            set_gated_world_summary: Some(summarize_diffs(&state.sequential_diffs)?),
            clear_sequential_diffs: true,
            append_event_log: vec![
                "summarization_gate: forwarded consolidated world summary".to_string(),
            ],
            ..StatePatch::default()
        }))
    }
}

fn context_manager_hook_node(state: SystemState, _ctx: NodeContext) -> impl FutureNode {
    async move {
        if state.context_utilization < CONTEXT_EVICTION_THRESHOLD {
            return Ok(NodeResult::Update(StatePatch::event(
                "context_manager_hook: utilization below eviction threshold",
            )));
        }

        let records = state
            .semantic_history
            .iter()
            .enumerate()
            .map(|(idx, trace)| MemoryRecord::new(format!("evicted-trace-{idx}"), trace.clone()))
            .collect();

        Ok(NodeResult::Update(StatePatch {
            replace_semantic_history: Some(vec![
                "--- semantic history evicted to vector DB ---".to_string(),
            ]),
            append_long_term_memory: records,
            context_utilization: Some(0.2),
            append_event_log: vec![
                "context_manager_hook: evicted semantic history to long-term memory".to_string(),
            ],
            ..StatePatch::default()
        }))
    }
}

fn subconscious_eval_node(state: SystemState, _ctx: NodeContext) -> impl FutureNode {
    async move {
        let summary = state
            .gated_world_summary
            .clone()
            .unwrap_or(GatedWorldSummary {
                macro_trend: "Cron review found no gated world-state package.".to_string(),
                critical_events: 0,
                total_magnitude: 0,
            });

        let directive = if summary.critical_events > 0 || summary.total_magnitude >= 50 {
            "STEERING_DIRECTIVE: High mutability detected. Lower sub-agent temperature and require retrieval before spawning."
        } else {
            "STEERING_DIRECTIVE: System stable. Preserve current execution policy."
        };

        Ok(NodeResult::Update(StatePatch {
            subconscious_steering: Some(directive.to_string()),
            trigger_subconscious: Some(false),
            cron_due: Some(false),
            clear_gated_world_summary: true,
            append_event_log: vec![format!(
                "subconscious_eval: digested summary '{}'",
                summary.macro_trend
            )],
            ..StatePatch::default()
        }))
    }
}

fn automated_loop_router(state: &SystemState) -> &'static str {
    if state.channel_response.is_empty() {
        "agent_execution"
    } else {
        "context_manager_hook"
    }
}

fn subconscious_router(state: &SystemState) -> &'static str {
    if state.trigger_subconscious || state.cron_due || state.gated_world_summary.is_some() {
        "subconscious_eval"
    } else {
        "END"
    }
}

fn retrieve_context(memory: &[MemoryRecord], query: &str) -> Vec<String> {
    let query = query.to_ascii_lowercase();
    memory
        .iter()
        .filter(|record| {
            query.contains(&record.key.to_ascii_lowercase())
                || record
                    .key
                    .split(['-', '_'])
                    .any(|term| !term.is_empty() && query.contains(term))
        })
        .map(|record| record.text.clone())
        .collect()
}

fn summarize_diffs(diffs: &[WorldDiff]) -> Result<GatedWorldSummary> {
    if diffs.is_empty() {
        return Err(TinyAgentsError::Validation(
            "summarization gate received no diffs".to_string(),
        ));
    }

    let critical_events = diffs
        .iter()
        .filter(|diff| diff.status != "stable" || diff.magnitude >= 50)
        .count();
    let total_magnitude = diffs.iter().map(|diff| diff.magnitude).sum();

    Ok(GatedWorldSummary {
        macro_trend: format!(
            "Aggregated {} operational shifts; {} critical events; total magnitude {}%.",
            diffs.len(),
            critical_events,
            total_magnitude
        ),
        critical_events,
        total_magnitude,
    })
}

fn contains_any(haystack: &str, needles: &[&str]) -> bool {
    let haystack = haystack.to_ascii_lowercase();
    needles.iter().any(|needle| haystack.contains(needle))
}

trait FutureNode:
    std::future::Future<Output = Result<NodeResult<StatePatch>>> + std::marker::Send + 'static
{
}

impl<T> FutureNode for T where
    T: std::future::Future<Output = Result<NodeResult<StatePatch>>> + std::marker::Send + 'static
{
}

//! Feature/integration tests for the harness durable-observability
//! infrastructure (`harness::observability`).
//!
//! Complements the existing `e2e_observability.rs` (which drives a full harness
//! run through the journal + Langfuse exporter) by exercising the durable
//! surfaces directly and offline: latency rollups derived from observation
//! timestamps, the in-memory journal's offset/retention/stale-offset contract,
//! the status store's lineage queries with terminal-vs-active eviction, and the
//! `FanOutSink` / `RedactingSink` listener sinks.
//!
//! Deterministic and offline — observations are hand-built with fixed
//! timestamps.

use std::sync::Arc;

use tinyagents_harness::events::{
    AgentEvent, EventListener, EventRecord, HarnessRunStatus, RecordingListener,
};
use tinyagents_harness::ids::{CallId, ComponentId, EventId, ExecutionStatus, RunId, ThreadId};
use tinyagents_harness::observability::{
    AgentLatencyMetrics, AgentObservation, FanOutSink, HarnessEventJournal, HarnessStatusStore,
    InMemoryEventJournal, InMemoryStatusStore, RedactingSink,
};

// ── Latency metrics from observations ───────────────────────────────────────

fn obs(run: &str, offset: u64, ts_ms: u64, event: AgentEvent) -> AgentObservation {
    let run_id = RunId::new(run);
    AgentObservation {
        event_id: EventId::new(format!("e-{offset}")),
        run_id: run_id.clone(),
        parent_run_id: None,
        root_run_id: run_id,
        offset,
        ts_ms,
        event,
    }
}

#[test]
fn latency_metrics_correlate_started_and_completed_by_call_id() {
    let observations = vec![
        obs(
            "r1",
            0,
            1_000,
            AgentEvent::RunStarted {
                run_id: RunId::new("r1"),
                thread_id: None,
            },
        ),
        obs(
            "r1",
            1,
            1_000,
            AgentEvent::ModelStarted {
                call_id: CallId::new("m1"),
                model: "test-model".into(),
            },
        ),
        obs(
            "r1",
            2,
            1_150,
            AgentEvent::ModelCompleted {
                call_id: CallId::new("m1"),
                started_at_ms: None,
                usage: None,
                input: None,
                output: None,
            },
        ),
        obs(
            "r1",
            3,
            1_150,
            AgentEvent::ToolStarted {
                call_id: CallId::new("t1"),
                tool_name: "search".into(),
            },
        ),
        obs(
            "r1",
            4,
            1_200,
            AgentEvent::ToolCompleted {
                call_id: CallId::new("t1"),
                tool_name: "search".into(),
                started_at_ms: None,
                input: None,
                output: None,
                duration_ms: None,
                output_bytes: None,
                error: None,
            },
        ),
        obs(
            "r1",
            5,
            1_500,
            AgentEvent::RunCompleted {
                run_id: RunId::new("r1"),
            },
        ),
    ];

    let metrics = AgentLatencyMetrics::from_observations(&observations);
    assert_eq!(metrics.run_elapsed_ms, Some(500)); // 1500 - 1000
    assert_eq!(metrics.model_calls.len(), 1);
    assert_eq!(metrics.model_calls[0].elapsed_ms, 150); // 1150 - 1000
    assert_eq!(metrics.model_calls[0].name, "test-model");
    assert_eq!(metrics.average_model_ms(), Some(150));
    assert_eq!(metrics.tool_calls.len(), 1);
    assert_eq!(metrics.tool_calls[0].elapsed_ms, 50); // 1200 - 1150
    assert_eq!(metrics.max_tool_ms, 50);
}

#[test]
fn latency_metrics_ignore_calls_without_a_completion() {
    // A ModelStarted with no matching ModelCompleted yields no model latency.
    let observations = vec![obs(
        "r2",
        0,
        0,
        AgentEvent::ModelStarted {
            call_id: CallId::new("m1"),
            model: "m".into(),
        },
    )];
    let metrics = AgentLatencyMetrics::from_observations(&observations);
    assert!(metrics.model_calls.is_empty());
    assert_eq!(metrics.total_model_ms, 0);
    assert_eq!(metrics.run_elapsed_ms, None);
}

// ── In-memory journal: offsets, retention, stale offsets ────────────────────

#[tokio::test]
async fn journal_appends_at_dense_offsets_and_replays_from_offset() {
    let journal = InMemoryEventJournal::new();
    for i in 0..3 {
        let offset = journal
            .append(obs(
                "run",
                i,
                i,
                AgentEvent::RunStarted {
                    run_id: RunId::new("run"),
                    thread_id: None,
                },
            ))
            .await
            .unwrap();
        assert_eq!(offset, i);
    }
    assert_eq!(journal.len("run"), 3);

    // Replay from 0 returns all; from a mid-offset returns the tail.
    assert_eq!(journal.read_from("run", 0).await.unwrap().len(), 3);
    assert_eq!(journal.read_from("run", 2).await.unwrap().len(), 1);
    // Unknown run replays empty rather than erroring.
    assert!(journal.read_from("nope", 0).await.unwrap().is_empty());
}

#[tokio::test]
async fn journal_read_filtered_selects_by_event_kind() {
    let journal = InMemoryEventJournal::new();
    journal
        .append(obs(
            "run",
            0,
            0,
            AgentEvent::RunStarted {
                run_id: RunId::new("run"),
                thread_id: None,
            },
        ))
        .await
        .unwrap();
    journal
        .append(obs(
            "run",
            1,
            0,
            AgentEvent::ToolStarted {
                call_id: CallId::new("t1"),
                tool_name: "x".into(),
            },
        ))
        .await
        .unwrap();

    let only_tools = journal
        .read_filtered("run", 0, &["tool.started"])
        .await
        .unwrap();
    assert_eq!(only_tools.len(), 1);
    assert_eq!(only_tools[0].event.kind(), "tool.started");
    // A bounded replay window truncates.
    assert_eq!(journal.read_window("run", 0, 1).await.unwrap().len(), 1);
}

#[tokio::test]
async fn journal_evicts_oldest_run_and_flags_stale_offsets() {
    // Cap of one run: appending a second evicts the first.
    let journal = InMemoryEventJournal::with_max_runs(1);
    journal
        .append(obs(
            "old",
            0,
            0,
            AgentEvent::RunStarted {
                run_id: RunId::new("old"),
                thread_id: None,
            },
        ))
        .await
        .unwrap();
    journal
        .append(obs(
            "new",
            0,
            0,
            AgentEvent::RunStarted {
                run_id: RunId::new("new"),
                thread_id: None,
            },
        ))
        .await
        .unwrap();

    assert_eq!(journal.run_count(), 1);
    // A consumer resuming from a now-evicted run's saved offset is told the
    // offset is stale rather than silently getting an empty replay.
    assert!(journal.read_from("old", 0).await.is_err());
}

// ── Status store: lineage queries + eviction ────────────────────────────────

fn status(run: &str, root: &str, thread: Option<&str>, terminal: bool) -> HarnessRunStatus {
    let mut s = HarnessRunStatus::new(RunId::new(run), ComponentId::new("agent"));
    s.root_run_id = RunId::new(root);
    s.thread_id = thread.map(ThreadId::new);
    if terminal {
        s.mark_completed();
    }
    s
}

#[tokio::test]
async fn status_store_answers_thread_root_and_active_queries() {
    let store = InMemoryStatusStore::new();
    // Two children of one root; one still active, one terminal.
    store
        .put_status(status("child-a", "root", Some("thread-1"), false))
        .await
        .unwrap();
    store
        .put_status(status("child-b", "root", Some("thread-1"), true))
        .await
        .unwrap();
    store
        .put_status(status("other", "other-root", Some("thread-2"), true))
        .await
        .unwrap();

    assert_eq!(store.list_by_root("root").await.unwrap().len(), 2);
    assert_eq!(store.list_by_thread("thread-1").await.unwrap().len(), 2);
    assert_eq!(store.list_by_thread("thread-2").await.unwrap().len(), 1);

    // Only the non-terminal child is active.
    let active = store.list_active().await.unwrap();
    assert_eq!(active.len(), 1);
    assert_eq!(active[0].run_id.as_str(), "child-a");

    let fetched = store.get_status("child-b").await.unwrap().unwrap();
    assert_eq!(fetched.status, ExecutionStatus::Completed);
}

#[tokio::test]
async fn status_store_evicts_terminal_runs_but_keeps_active_ones() {
    // Cap of one: an active run must never be evicted to make room.
    let store = InMemoryStatusStore::with_max_runs(1);
    store
        .put_status(status("active", "active", None, false))
        .await
        .unwrap();
    store
        .put_status(status("terminal", "terminal", None, true))
        .await
        .unwrap();

    // The active run survives even though the cap was exceeded.
    assert!(store.get_status("active").await.unwrap().is_some());
}

// ── Listener sinks: fan-out + redaction ─────────────────────────────────────

fn record(offset: u64, event: AgentEvent) -> EventRecord {
    EventRecord {
        id: EventId::new(format!("e-{offset}")),
        offset,
        event,
    }
}

#[test]
fn fan_out_sink_broadcasts_to_every_listener() {
    let a = Arc::new(RecordingListener::new());
    let b = Arc::new(RecordingListener::new());
    let sink = FanOutSink::new().with(a.clone()).with(b.clone());
    assert_eq!(sink.len(), 2);

    sink.on_event(&record(
        0,
        AgentEvent::RunStarted {
            run_id: RunId::new("r"),
            thread_id: None,
        },
    ));
    assert_eq!(a.events().len(), 1);
    assert_eq!(b.events().len(), 1);
}

#[test]
fn redacting_sink_masks_secrets_in_string_fields_before_forwarding() {
    let downstream = Arc::new(RecordingListener::new());
    let sink = RedactingSink::new(downstream.clone(), vec!["sk-secret".to_string()]);

    // The secret rides in the `model` field of ModelStarted.
    sink.on_event(&record(
        0,
        AgentEvent::ModelStarted {
            call_id: CallId::new("m1"),
            model: "provider/sk-secret".into(),
        },
    ));

    let seen = downstream.events();
    assert_eq!(seen.len(), 1);
    match &seen[0].event {
        AgentEvent::ModelStarted { model, .. } => {
            assert!(!model.contains("sk-secret"));
            assert!(model.contains("[REDACTED]"));
        }
        other => panic!("unexpected event: {other:?}"),
    }
}

#[test]
fn redacting_sink_with_no_secrets_is_pass_through() {
    let downstream = Arc::new(RecordingListener::new());
    let sink = RedactingSink::new(downstream.clone(), Vec::new());
    sink.on_event(&record(
        0,
        AgentEvent::RunCompleted {
            run_id: RunId::new("r"),
        },
    ));
    assert_eq!(downstream.events().len(), 1);
}

//! End-to-end contracts for graph support surfaces: file-backed checkpoints and
//! the public graph testkit helpers.

use std::time::{SystemTime, UNIX_EPOCH};

use serde_json::json;

use tinyagents_graph::testkit::{
    GraphEventRecorder, RetryCountingNode, assert_graph, fanout_node, interrupting_node, noop_node,
    run_recorded, scripted_route_node, scripted_update_node, subagent_fake_node,
    subgraph_test_node,
};
use tinyagents_graph::*;
use tinyagents_harness::ids::ExecutionStatus;
use tinyagents_harness::*;
use tinyagents_registry::*;
use tinyinference_llm::usage::UsageTotals;

fn temp_path(name: &str) -> std::path::PathBuf {
    std::env::temp_dir().join(format!(
        "tinyagents-{name}-{}-{}",
        std::process::id(),
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ))
}

#[tokio::test]
async fn file_checkpointer_persists_lists_copies_prunes_and_deletes_threads() {
    let dir = temp_path("file-checkpointer");
    let checkpointer = std::sync::Arc::new(FileCheckpointer::<i32>::new(&dir));
    assert_eq!(checkpointer.base_dir(), dir.as_path());

    let graph = GraphBuilder::<i32, i32>::overwrite()
        .add_node("a", |s, _c: NodeContext| async move {
            Ok(NodeResult::Update(s + 1))
        })
        .add_node("b", |s, _c: NodeContext| async move {
            Ok(NodeResult::Update(s + 1))
        })
        .set_entry("a")
        .add_edge("a", "b")
        .set_finish("b")
        .compile()
        .expect("graph compiles")
        .with_checkpointer(checkpointer.clone());

    let run = graph
        .run_with_thread("thread/with space", 0)
        .await
        .expect("threaded file-backed run succeeds");
    assert_eq!(run.state, 2);
    assert_eq!(run.status.status, ExecutionStatus::Completed);

    let list = checkpointer.list("thread/with space").await.expect("list");
    assert_eq!(list.len(), 2);
    assert_eq!(list[0].source, CheckpointSource::Loop);
    assert_eq!(
        CheckpointSource::parse("fork"),
        Some(CheckpointSource::Fork)
    );
    assert_eq!(CheckpointSource::Update.to_string(), "update");

    let latest = checkpointer
        .get("thread/with space", None)
        .await
        .expect("get latest")
        .expect("latest checkpoint");
    assert_eq!(latest.state, 2);
    assert_eq!(
        latest.parent_checkpoint_id.as_deref(),
        Some(list[0].checkpoint_id.as_str())
    );

    let tuple = checkpointer
        .get_tuple(CheckpointConfig::latest("thread/with space"))
        .await
        .expect("tuple")
        .expect("tuple present");
    assert_eq!(tuple.config.thread_id, "thread/with space");
    assert!(tuple.parent_config.is_some());

    checkpointer
        .copy_thread("thread/with space", "copy-target")
        .await
        .expect("copy thread");
    let copied = checkpointer.list("copy-target").await.expect("copied list");
    assert_eq!(copied.len(), 2);
    assert!(copied.iter().all(|m| m.thread_id == "copy-target"));

    let threads = checkpointer.list_threads().await.expect("threads");
    assert!(threads.contains(&"thread/with space".to_string()));
    assert!(threads.contains(&"copy-target".to_string()));

    let removed = checkpointer
        .delete_checkpoints("copy-target", &[copied[0].checkpoint_id.clone()])
        .await
        .expect("delete one");
    assert_eq!(removed, 1);
    assert_eq!(checkpointer.list("copy-target").await.unwrap().len(), 1);

    let pruned = checkpointer
        .prune("thread/with space", 1)
        .await
        .expect("prune keeps latest and ancestors");
    assert_eq!(pruned, 0);

    checkpointer
        .delete_thread("copy-target")
        .await
        .expect("delete thread");
    assert!(checkpointer.list("copy-target").await.unwrap().is_empty());
    let _ = std::fs::remove_dir_all(&dir);
}

#[tokio::test]
async fn file_checkpointer_state_history_walks_lineage_newest_first() {
    // Exercises FileCheckpointer's single-pass `state_history` override: the
    // whole thread file is read once and the parent lineage walked in memory,
    // returning snapshots newest-first with the lineage spine intact.
    let dir = temp_path("file-checkpointer-history");
    let checkpointer = std::sync::Arc::new(FileCheckpointer::<i32>::new(&dir));
    let graph = GraphBuilder::<i32, i32>::overwrite()
        .add_node("a", |s, _c: NodeContext| async move {
            Ok(NodeResult::Update(s + 1))
        })
        .add_node("b", |s, _c: NodeContext| async move {
            Ok(NodeResult::Update(s + 1))
        })
        .set_entry("a")
        .add_edge("a", "b")
        .set_finish("b")
        .compile()
        .expect("graph compiles")
        .with_checkpointer(checkpointer.clone());

    graph
        .run_with_thread("hist-thread", 0)
        .await
        .expect("threaded run succeeds");

    // Full history is newest-first, and each snapshot's parent addresses the
    // next (older) snapshot — the lineage spine walked in memory.
    let history = graph
        .get_state_history("hist-thread", None)
        .await
        .expect("state history");
    assert_eq!(history.len(), 2);
    assert_eq!(history[0].values, 2);
    assert_eq!(history[1].values, 1);
    assert_eq!(
        history[0]
            .parent_config
            .as_ref()
            .and_then(|c| c.checkpoint_id.as_deref()),
        history[1].config.checkpoint_id.as_deref(),
        "newest checkpoint's parent is the older checkpoint"
    );

    // `limit` caps to the most recent snapshots.
    let recent = graph
        .get_state_history("hist-thread", Some(1))
        .await
        .expect("limited history");
    assert_eq!(recent.len(), 1);
    assert_eq!(recent[0].values, 2);

    let _ = std::fs::remove_dir_all(&dir);
}

#[tokio::test]
async fn graph_testkit_helpers_drive_recorded_graphs_and_assertions() {
    let checkpointer = std::sync::Arc::new(InMemoryCheckpointer::<i32>::new());
